def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i

        # Determine the sign part
        if not terms:
            # First term
            if coeff < 0:
                sign = '-'
            else:
                sign = ''
        else:
            # Subsequent terms
            if coeff < 0:
                sign = '-'
            else:
                sign = '+'

        # Determine the coefficient part
        abs_coeff = abs(coeff)
        if degree == 0:
            # Constant term
            coeff_part = str(abs_coeff)
        else:
            # Variable term
            if abs_coeff == 1:
                coeff_part = ''
            else:
                coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)
```

