def mod_inverse(a, b):
    def extended_gcd(x, y):
        if x == 0:
            return (y, 0, 1)
        else:
            g, x1, y1 = extended_gcd(y % x, x)
            return (g, y1 - (y // x) * x1, x1)

    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None
    else:
        return x % b

